import{_ as u,a0 as a,w as r,s as l,ao as s,I as p,x as n,a1 as i,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const G=JSON.parse('{"title":"英偉達在提升 Linux 上的 GPU 使用體驗上邁出了一大步 | LCTT x X-CMD","titleTemplate":false,"description":"英偉達在提升 Linux 上的 GPU 使用體驗上邁出了一大步 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"英偉達在提升 Linux 上的 GPU 使用體驗上邁出了一大步 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"英偉達在提升 Linux 上的 GPU 使用體驗上邁出了一大步 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220512 NVIDIA Takes a Big Step to Improve its GPU Experience on Linux","title":"英偉達在提升 Linux 上的 GPU 使用體驗上邁出了一大步","tag":"202205","desc":""},"relativePath":"202205/20220512 NVIDIA Takes a Big Step to Improve its GPU Experience on Linux.md","filePath":"[post].md"}'),d={name:"202205/20220512 NVIDIA Takes a Big Step to Improve its GPU Experience on Linux.md"};function x(m,t,f,T,v,P){const e=a("Link");return r(),l("div",null,[t[23]||(t[23]=s('<h1 id="英偉達在提升-linux-上的-gpu-使用體驗上邁出了一大步" tabindex="-1">英偉達在提升 Linux 上的 GPU 使用體驗上邁出了一大步 <a class="header-anchor" href="#英偉達在提升-linux-上的-gpu-使用體驗上邁出了一大步" aria-label="Permalink to “英偉達在提升 Linux 上的 GPU 使用體驗上邁出了一大步”">​</a></h1><blockquote><p>英偉達公司提升其 GPU 在 Linux 上的體驗的重大開源計劃終於來了。</p></blockquote><p><img src="https://news.itsfoss.com/wp-content/uploads/2022/05/linus-torvalds-nvidia.jpg" alt=""></p><p>Linus Torvalds 聽到這個消息一定會很高興……</p><p>英偉達終於公佈了提升 Linux 上的 GPU 使用體驗的開源計劃。</p><p>不過不幸的是，和你想像的可能不完全一樣，你仍然會看到一些專有的驅動程序。</p><p>但是，它的意義不亞於甩掉專有驅動程序。</p><p>具體來説就是，<strong>英偉達發佈了開源的 GPU 內核模組，支持數據中心所用的 GPU 和消費級顯卡（GeForce/RTX）</strong>。</p><p>此外，它同時採用 GPL/MIT 兩種許可證，聽起來很棒，對嗎？</p><h3 id="此舉對-linux-桌面用户有什麼幫助" tabindex="-1">此舉對 Linux 桌面用户有什麼幫助？ <a class="header-anchor" href="#此舉對-linux-桌面用户有什麼幫助" aria-label="Permalink to “此舉對 Linux 桌面用户有什麼幫助？”">​</a></h3><p>開源的 GPU 內核模組有助於改善內核和專有驅動程序之間的交互。</p><p>所以，此舉對 <strong>遊戲玩家和開發者</strong> 都有利，阻礙與英偉達專有驅動程序配合的問題最終會被消除。</p><p>發佈公告中提到的技術收益包括：</p><blockquote><p>開發者可以跟蹤到具體的代碼路徑，並觀察到內核事件調度是如何與他們的工作負載交互的，從而在調試時更快定位根本原因。此外，企業軟件開發者可以將該驅動程序無縫地集成到他們為項目定製的 Linux 內核中。</p><p>來自 Linux 最終用户社區的投入和評價，將進一步提升英偉達 GPU 驅動程序的質量和安全性。</p></blockquote><p>而從最終用户或者遊戲玩家方面來看，你會發現安裝將更便捷，整體會更安全。</p><p>Canonical 和 SUSE 會立即為他們的企業用户打包該開源內核模組，而其它廠商也會很快跟進。</p><p>當它可以用在桌面環境時，Canonical 應該會在未來幾個月內把這個內核模組放到 Ubuntu 22.04 LTS 版本中。其它的 Linux 發行版應該也會做相應的升級。</p><h3 id="現在可以試用嗎" tabindex="-1">現在可以試用嗎？ <a class="header-anchor" href="#現在可以試用嗎" aria-label="Permalink to “現在可以試用嗎？”">​</a></h3><p><img src="https://news.itsfoss.com/wp-content/uploads/2022/05/nvidia-opensource-linux-drivers-1024x576.jpg" alt=""></p><p>這個開源的 GPU 內核模組的第一個版本是 R515，它是作為 CUDA 工具集 11.7 一部分一起發佈的開發驅動程序。</p>',20)),p("p",null,[t[2]||(t[2]=n("你可以從 ",-1)),i(e,{href:"https://www.nvidia.com/en-us/drivers/unix/"},{default:o(()=>[...t[0]||(t[0]=[n("官方驅動下載頁面",-1)])]),_:1}),t[3]||(t[3]=n(" 或者從 ",-1)),i(e,{href:"https://developer.nvidia.com/cuda-downloads"},{default:o(()=>[...t[1]||(t[1]=[n("CUDA 下載頁面",-1)])]),_:1}),t[4]||(t[4]=n(" 找到。",-1))]),t[24]||(t[24]=s('<p>雖然它被認為可用於數據中心生產環境，<strong>但對於 GeForce 或者工作站 GPU 來説，還處於 alpha 階段</strong>。</p><p>事實上，在 Turing 和 Ampere 架構的 GPU 型號上可以使用這個驅動程序，以使用 Vulkan 和 Optix 中的 <strong>多顯示器、G-Sync、Nvidia RTX 光線追蹤</strong> 等功能。</p><p>然而，除非你想運行一些“實驗性測試”，否則還是等幾個月，以便直接從你的 Linux 發行版中獲得為桌面用户發佈的穩定版。</p><h3 id="對-nouveau-驅動程序開發也有益" tabindex="-1">對 Nouveau 驅動程序開發也有益 <a class="header-anchor" href="#對-nouveau-驅動程序開發也有益" aria-label="Permalink to “對 Nouveau 驅動程序開發也有益”">​</a></h3><p>不僅僅是提升了專有驅動程序的體驗，公佈的這個開源 GPU 內核代碼也會改善 Nouveau 驅動。</p><p>正如發佈公告所説：</p><blockquote><p>Nouveau 可以利用英偉達驅動程序所使用的同樣固件，它公開了許多 GPU 功能，例如時鐘管理、散熱管理，可以為樹內的 Nouveau 驅動程序帶來新的特性。</p><p>請關注未來的驅動更新以及在 Github 上的合作。</p></blockquote><p>英偉達公司提到並可能合作改進開源的英偉達驅動程序（即 Nouveau），這真是太好了。</p><p>這也很好地表明瞭，他們確實希望為 Linux 提供一個更好的開源驅動程序版本。</p><h3 id="開源-nivida-驅動程序的未來" tabindex="-1">開源 Nivida 驅動程序的未來？ <a class="header-anchor" href="#開源-nivida-驅動程序的未來" aria-label="Permalink to “開源 Nivida 驅動程序的未來？”">​</a></h3><p>毋容置疑，英偉達計劃不斷髮布開源的 GPU 內核模組。</p><p>所以，儘管他們不會單獨開源他們的驅動程序，但我們仍然可以寄希望於 Nouveau 釋放所有的顯卡特性。</p>',12)),p("p",null,[t[6]||(t[6]=n("想知道他們更多的計劃，你可以參考 ",-1)),i(e,{href:"https://developer.nvidia.com/blog/nvidia-releases-open-source-gpu-kernel-modules/"},{default:o(()=>[...t[5]||(t[5]=[n("官方的發佈聲明",-1)])]),_:1}),t[7]||(t[7]=n("。",-1))]),t[25]||(t[25]=p("p",null,[p("em",null,"你如何看待這件事？英偉達最終會愛開源和 Linux 嗎？嗯，至少這是一個好的開始。在下面的評論區分享你的想法吧。")],-1)),t[26]||(t[26]=p("hr",null,null,-1)),p("p",null,[t[9]||(t[9]=n("via: ",-1)),i(e,{href:"https://news.itsfoss.com/nvidia-open-source-linux/"},{default:o(()=>[...t[8]||(t[8]=[n("https://news.itsfoss.com/nvidia-open-source-linux/",-1)])]),_:1})]),p("p",null,[t[14]||(t[14]=n("作者：",-1)),i(e,{href:"https://news.itsfoss.com/author/ankush/"},{default:o(()=>[...t[10]||(t[10]=[n("Ankush Das",-1)])]),_:1}),t[15]||(t[15]=n(" 選題：",-1)),i(e,{href:"https://github.com/lkxed"},{default:o(()=>[...t[11]||(t[11]=[n("lkxed",-1)])]),_:1}),t[16]||(t[16]=n(" 譯者：",-1)),i(e,{href:"https://github.com/chunyang-wen"},{default:o(()=>[...t[12]||(t[12]=[n("chunyang-wen",-1)])]),_:1}),t[17]||(t[17]=n(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[13]||(t[13]=[n("wxy",-1)])]),_:1})]),p("p",null,[t[20]||(t[20]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[18]||(t[18]=[n("LCTT",-1)])]),_:1}),t[21]||(t[21]=n(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:o(()=>[...t[19]||(t[19]=[n("Linux中國",-1)])]),_:1}),t[22]||(t[22]=n(" 榮譽推出",-1))])])}const U=u(d,[["render",x]]);export{G as __pageData,U as default};
